import java.text.Collator;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;

public record CustomerFilter(String nameFilter, List<CustomerStatus> statuses) {

    public static CustomerFilter empty() {
        return new CustomerFilter("", List.of());
    }

    public boolean matches(Customer customer) {
        if (!matchesStatus(customer)) {
            return false;
        }
        return matchesName(customer);
    }

    private boolean matchesStatus(Customer customer) {
        if (statuses.isEmpty()) {
            return true;
        }
        return statuses.contains(customer.status());
    }

    private boolean matchesName(Customer customer) {
        if (nameFilter == null || nameFilter.trim().isEmpty()) {
            return true;
        }

        String[] terms = nameFilter.trim().split("\\s+");
        String firstName = customer.firstName();
        String lastName = customer.lastName();

        Collator collator = Collator.getInstance(Locale.ROOT);
        collator.setStrength(Collator.PRIMARY);

        for (String term : terms) {
            if (!containsIgnoreCaseAndAccents(firstName, term, collator)
                    && !containsIgnoreCaseAndAccents(lastName, term, collator)) {
                return false;
            }
        }
        return true;
    }

    private static boolean containsIgnoreCaseAndAccents(String text, String substring, Collator collator) {
        if (text == null || substring == null || substring.isEmpty()) {
            return substring == null || substring.isEmpty();
        }

        for (int i = 0; i <= text.length() - substring.length(); i++) {
            String candidate = text.substring(i, i + substring.length());
            if (collator.equals(candidate, substring)) {
                return true;
            }
        }
        return false;
    }
}
