import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

public class DebounceHandler {
    private final ScheduledExecutorService executor = Executors.newScheduledThreadPool(1, r -> {
        Thread t = new Thread(r, "debounce-handler");
        t.setDaemon(true);
        return t;
    });
    private final Runnable action;
    private final long delayMs;
    private ScheduledFuture<?> scheduledTask;

    public DebounceHandler(Runnable action, long delayMs) {
        this.action = action;
        this.delayMs = delayMs;
    }

    public void handle(Runnable setup) {
        if (scheduledTask != null) {
            scheduledTask.cancel(false);
        }
        setup.run();
        scheduledTask = executor.schedule(action, delayMs, TimeUnit.MILLISECONDS);
    }
}
